
.opening-shell {
  width: min(680px, 100%);
  margin: 8px auto;
  padding: 14px;
  display: grid;
  gap: 14px;
  color: #f6efdf;
  background:
    radial-gradient(circle at top left, rgba(216, 175, 88, 0.16), transparent 24%),
    radial-gradient(circle at bottom right, rgba(129, 29, 29, 0.16), transparent 28%),
    linear-gradient(180deg, rgba(22, 16, 18, 0.98), rgba(10, 10, 14, 0.98));
  border: 1px solid rgba(229, 198, 124, 0.22);
  border-radius: 22px;
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.34);
  font-family: Georgia, 'Times New Roman', serif;
}

.panel {
  padding: 16px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.04);
}

.hero-card,
.action-row,
.status-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.hero-card h1 {
  margin: 0;
}

.hero-card p {
  margin: 6px 0 0;
  color: rgba(246, 239, 223, 0.76);
}

.field-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.field {
  display: grid;
  gap: 6px;
}

.field span,
.status-row span {
  color: rgba(235, 222, 197, 0.78);
  font-size: 12px;
}

.field-full {
  grid-column: 1 / -1;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 11px 12px;
  color: #f6efdf;
  background: rgba(8, 10, 13, 0.78);
  border: 1px solid rgba(232, 198, 127, 0.18);
  border-radius: 12px;
  font: inherit;
}

.compact-panel {
  display: grid;
  gap: 10px;
}

.collapsed-shell {
  width: min(680px, 100%);
  padding-top: 6px;
  padding-bottom: 6px;
}

.pass {
  color: #9fdb9f;
}

.fail {
  color: #ffb5b5;
}

.error-list {
  margin: 0;
  padding-left: 18px;
  color: #ffcece;
}

.primary-button,
.secondary-button {
  appearance: none;
  border: 0;
  border-radius: 999px;
  min-height: 42px;
  padding: 0 18px;
  font: inherit;
  cursor: pointer;
}

.primary-button {
  color: #160f0f;
  background: linear-gradient(135deg, #d3b16a, #f2e3bf);
}

.primary-button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.secondary-button {
  color: #f6efdf;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

@media (max-width: 760px) {
  .field-grid {
    grid-template-columns: 1fr;
  }

  .hero-card,
  .action-row,
  .status-row {
    flex-direction: column;
    align-items: flex-start;
  }
}
